// Mapea el correo entrante al payload de intake normalizado del contrato
// ONIA Core v0.5.0 (intakePolicy, canal email_shared).
// ORG_BY_MAILBOX: a que organizacion pertenece cada buzon destino.
// Completar con los IDs reales (tabla organizations de DentalGest).
const ORG_BY_MAILBOX = {
  "recepcion@tuclinica.bo": "REEMPLAZAR_ORG_ID",
};
const DEFAULT_ORG_ID = "REEMPLAZAR_ORG_ID";

const results = [];
for (const item of $input.all()) {
  const email = item.json;
  const toAddress = String(email.to || "").toLowerCase();
  const mailboxKey = Object.keys(ORG_BY_MAILBOX).find((mb) => toAddress.includes(mb));
  const organizationId = mailboxKey ? ORG_BY_MAILBOX[mailboxKey] : DEFAULT_ORG_ID;

  const fromRaw = String(email.from || "");
  const emailMatch = fromRaw.match(/<([^>]+)>/);
  const fromEmail = (emailMatch ? emailMatch[1] : fromRaw).trim().toLowerCase();
  const fromName = fromRaw.replace(/<[^>]+>/, "").replace(/"/g, "").trim() || undefined;

  const subject = String(email.subject || "(sin asunto)");
  const text = String(email.textPlain || email.textHtml || "").slice(0, 1500);

  results.push({
    json: {
      organizationId,
      channel: "email_shared",
      message: `${subject}\n\n${text}`.trim(),
      contact: { name: fromName, email: fromEmail },
      receivedAt: email.date ? new Date(email.date).toISOString() : new Date().toISOString(),
    },
  });
}
return results;
